const ev = $input.first().json;
const body = ev.body || ev;
const data = body.data || body;
const key = data.key || {};

if (key.fromMe) return [];
const remoteJid = key.remoteJid || '';
if (remoteJid.endsWith('@g.us')) return [];

const from = remoteJid.replace('@s.whatsapp.net', '').replace('@c.us', '');
const messageId = key.id;
if (!messageId || !from) {
  throw new Error('Payload inválido: falta key.id o remoteJid');
}

const msg = data.message || {};
let text = '';
let type = 'unknown';
if (msg.conversation) { text = msg.conversation; type = 'text'; }
else if (msg.extendedTextMessage?.text) { text = msg.extendedTextMessage.text; type = 'text'; }
else if (msg.imageMessage) { type = 'image'; text = msg.imageMessage.caption || ''; }
else if (msg.audioMessage) { type = 'audio'; }
else if (msg.videoMessage) { type = 'video'; text = msg.videoMessage.caption || ''; }
else if (msg.documentMessage) { type = 'document'; }
else if (msg.stickerMessage) { type = 'sticker'; }

return [{
  json: {
    message_id: messageId, from, push_name: data.pushName || null,
    type, body: text, raw_payload: body, received_at: new Date().toISOString(),
  }
}];

const resp = $input.first().json;
const content = resp.choices?.[0]?.message?.content || '{}';
let parsed;
try { parsed = JSON.parse(content); }
catch (e) { parsed = { intent: 'ruido', respuesta_cliente: 'Disculpa, hubo un error procesando tu mensaje.' }; }

const upstream = $('Ensamblar prompt OpenAI').first().json;
const cliente_msg_raw = upstream.cliente_body || '';

// Normalizar: lowercase + sin acentos + sin puntuación + colapsar espacios
function normalize(s) {
  return (s || '')
    .toLowerCase()
    .normalize('NFD').replace(/[̀-ͯ]/g, '')
    .replace(/[^a-z0-9\s]/g, ' ')
    .replace(/\s+/g, ' ').trim();
}
const norm = normalize(cliente_msg_raw);

// === Detección por prefijos (tolerante a typos comunes) ===
function detectarIntent(n, gptIntent) {
  if (/^\d{4}$/.test(n.replace(/\s/g, ''))) return 'confirmar_otp';
  if (/(cancel|anul|borra|no\squiero\sir|ya\sno\squiero)/.test(n)) return 'cancelar';
  if (/(mov|cambi|reprogr|pasal|pasar|muev)/.test(n)) return 'reprogramar';
  const tieneServ = /(refl|memor|espect)/.test(n);
  const tieneFecha = /(manana|hoy|lun|mart|mierc|juev|vier|sab|domin)/.test(n);
  const tieneHora = /(\d{1,2}\s*(am|pm|h)|\d{1,2}:\d{2})/.test(n);
  if ((tieneServ && (tieneFecha || tieneHora)) || (/(reserv|agend|quier|quisier)/.test(n) && tieneServ)) return 'agendar';
  return gptIntent;
}

// === Extracción regex tolerante para agendar/reprogramar ===
function extraerAgendar(n, raw) {
  const out = { servicio_solicitado: null, fecha_solicitada: null, hora_solicitada: null, sede_preferida: null };

  // Modalidad explícita en este turno — NO inferir default (fix bug cita Pau 2026-05-14)
  const tieneEspect = /(espect)/.test(n);
  const tieneParej = /\b(parej|pareja)\b/.test(n);
  const tieneIndiv = /\b(individual|solo\s+yo|para\s+m[ií]\b|sola?\b|yo\s+sol)/.test(n);
  let mod = null;
  if (tieneEspect) mod = 'espectador';
  else if (tieneParej) mod = 'pareja';
  else if (tieneIndiv) mod = 'individual';

  if (mod && n.includes('refl')) {
    if (mod === 'pareja') out.servicio_solicitado = 'Reflejo pareja';
    else if (mod === 'individual') out.servicio_solicitado = 'Reflejo individual';
    else if (mod === 'espectador') out.servicio_solicitado = 'Espectador Reflejo';
  } else if (mod && n.includes('memor')) {
    if (mod === 'pareja') out.servicio_solicitado = 'Memorable pareja';
    else if (mod === 'individual') out.servicio_solicitado = 'Memorable individual';
    else if (mod === 'espectador') out.servicio_solicitado = 'Espectador Memorable';
  }

  // Fecha
  const today = new Date();
  const todayBog = today.toLocaleDateString('en-CA', { timeZone: 'America/Bogota' });
  const [ty, tm, td] = todayBog.split('-').map(Number);
  if (/hoy/.test(n)) {
    out.fecha_solicitada = todayBog;
  } else if (/manana/.test(n)) {
    const tomorrow = new Date(Date.UTC(ty, tm - 1, td + 1));
    out.fecha_solicitada = tomorrow.toISOString().split('T')[0];
  } else {
    const diasMap = [
      { p: ['domin'], d: 0 },
      { p: ['lun'], d: 1 },
      { p: ['mart'], d: 2 },
      { p: ['mierc'], d: 3 },
      { p: ['juev'], d: 4 },
      { p: ['vier'], d: 5 },
      { p: ['sab'], d: 6 },
    ];
    for (const dm of diasMap) {
      if (dm.p.some(pre => new RegExp('\b' + pre).test(n))) {
        const refUTC = new Date(Date.UTC(ty, tm - 1, td));
        const todayDow = refUTC.getUTCDay();
        const offset = ((dm.d - todayDow + 7) % 7) || 7;
        const next = new Date(Date.UTC(ty, tm - 1, td + offset));
        out.fecha_solicitada = next.toISOString().split('T')[0];
        break;
      }
    }
  }

  // Hora — buscar en el texto raw para no perder los dos puntos
  const hm = (raw || '').match(/(\d{1,2})(?::(\d{2}))?\s*(am|pm|a\.\s*m\.|p\.\s*m\.|hrs?|h)?/i);
  if (hm) {
    let h = parseInt(hm[1]);
    const min = hm[2] ? parseInt(hm[2]) : 0;
    const ampm = hm[3] ? hm[3].toLowerCase().replace(/[\s.]/g, '') : '';
    if (ampm.startsWith('pm') && h < 12) h += 12;
    if (ampm.startsWith('am') && h === 12) h = 0;
    if (h >= 0 && h <= 23 && min >= 0 && min <= 59) {
      out.hora_solicitada = `${String(h).padStart(2,'0')}:${String(min).padStart(2,'0')}`;
    }
  }

  // Sede
  if (n.includes('bogot')) out.sede_preferida = 'Bogotá';
  else if (n.includes('cajic')) out.sede_preferida = 'Cajicá';

  return out;
}

