const intentOriginal = parsed.intent;
const intentDeterm = detectarIntent(norm, intentOriginal);
let datos = parsed.datos || {};

if (intentDeterm !== intentOriginal) {
  parsed.intent = intentDeterm;
}

if (parsed.intent === 'agendar' || parsed.intent === 'reprogramar') {
