const WF3_INTENTS = ['reprogramar', 'cancelar', 'confirmar_otp'];

let accion = 'responder_directo';
let respuesta_final = parsed.respuesta_cliente || 'Disculpa, no entendí. ¿Puedes repetir?';
let notificar_admin = false;

if (parsed.intent === 'agendar') {
  const faltantes = [];
  if (!datos.servicio_solicitado) faltantes.push('servicio (Reflejo, Memorable o Espectador, individual o en pareja)');
  if (!datos.fecha_solicitada) faltantes.push('fecha');
  if (!datos.hora_solicitada) faltantes.push('hora');
  if (!datos.sede_preferida) faltantes.push('sede (Bogotá o Cajicá)');

  if (faltantes.length === 0) {
    accion = 'agendar';
  } else {
    accion = 'responder_directo';
    const respGPT = parsed.respuesta_cliente || '';
    const dijoVerificar = /verific|comprob|busc|en un moment|momento por favor/i.test(respGPT);
    const preguntoAlgo = /\?\s*$/.test(respGPT.trim()) || /qu[eé]\b|cu[aá]l\b|d[oó]nde\b|cu[aá]ndo\b|prefier|gustar|individual|pareja/i.test(respGPT);
    if (dijoVerificar && !preguntoAlgo) {
      respuesta_final = `Casi listo, me falta: ${faltantes.join(', ')}. ¿Me lo confirmas?`;
    }
  }
} else if (parsed.intent === 'escalar_admin') {
  accion = 'responder_directo';
  notificar_admin = true;
} else if (WF3_INTENTS.includes(parsed.intent)) {
  accion = 'wf3';
} else if (parsed.intent === 'consultar_cita' && intentDeterm === 'consultar_cita') {
  const respGPT = parsed.respuesta_cliente || '';
  if (/precio|servicio|reflejo|memorable|catálog|catalog/i.test(respGPT)) {
    accion = 'responder_directo';
    respuesta_final = 'Solo puedo consultar las citas que tengas reservadas tú. ¿Tienes alguna cita conmigo? Si quieres reservar una nueva, dime servicio + fecha + hora + sede 🌿';
  }
} else if (!ENABLED.includes(parsed.intent)) {
  accion = 'responder_directo';
  respuesta_final = `No entendí del todo. ¿Me cuentas qué necesitas? Puedo ayudarte a reservar una terapia.`;
  notificar_admin = true;
}

return [{
  json: {
    accion, intent: parsed.intent,
    intent_original_gpt: intentOriginal,
    intent_overridden: intentDeterm !== intentOriginal,
    datos,
    respuesta_final, notificar_admin,
    cliente_id: upstream.cliente_id,
    cliente_whatsapp: upstream.cliente_whatsapp,
    cliente_body: upstream.cliente_body,
    _gpt_raw: parsed,
    wf2_payload: {
      cliente_id: upstream.cliente_id,
      cliente_whatsapp: upstream.cliente_whatsapp,
      servicio_solicitado: datos.servicio_solicitado,
      fecha_solicitada: datos.fecha_solicitada,
      hora_solicitada: datos.hora_solicitada,
      sede_preferida: datos.sede_preferida,
      genero_terapeuta_preferido: datos.genero_terapeuta_preferido || null,
      terapeuta_preferido: datos.terapeuta_preferido || null,
    },
    wf3_payload: {
      intent: parsed.intent,
      cliente_id: upstream.cliente_id,
      cliente_whatsapp: upstream.cliente_whatsapp,
      datos,
    }
  }
}];

